insert into public.categories (slug, name, parent_id, intro, blurb, image, sort_order, seo_title, seo_description, faqs) values ('kitchen', 'Kitchen & Dining', null, 'Kitchen & Dining at City Seller covers airtight containers, cookware and handy prep tools for Indian kitchens. Everything is chosen for daily use, easy cleaning and honest prices.', 'Airtight jars, tawas and choppers that keep your kitchen tidy and cooking quick.', '/placeholders/categories/kitchen.svg', 0, 'Kitchen & Dining Essentials Online at Best Prices', null, '[{"q":"Are your kitchen containers food-safe?","a":"Yes. Every container we list is made from food-grade, BPA-free plastic, glass or stainless steel, as mentioned in its specifications table."},{"q":"Can I use non-stick cookware on induction?","a":"Only if the product page says \"induction base\". Our tawas and pans list their compatible stovetops in the specs."},{"q":"How long does kitchen product delivery take?","a":"Most PIN codes receive orders in 4 to 8 days. Enter your PIN code on any product page for an estimate."}]'::jsonb) on conflict (slug) do nothing;
insert into public.categories (slug, name, parent_id, intro, blurb, image, sort_order, seo_title, seo_description, faqs) values ('storage', 'Storage & Organisation', null, 'Storage & Organisation products help you fit more into small Indian homes, from foldable wardrobe boxes to multi-tier racks. They suit rented flats, hostels and family homes alike.', 'Wardrobe organisers, saree covers and racks that make every shelf count.', '/placeholders/categories/storage.svg', 1, null, null, '[{"q":"Do the racks need drilling?","a":"Free-standing racks need no drilling. Wall-mounted items say so clearly in their specifications."},{"q":"Will the wardrobe boxes fit my almirah shelf?","a":"Check the dimensions row in the specs table and measure your shelf depth; most of our boxes suit standard 45 cm deep shelves."},{"q":"Are the fabric organisers washable?","a":"Wipe them with a damp cloth. Machine washing can weaken the stiffening boards."}]'::jsonb) on conflict (slug) do nothing;
insert into public.categories (slug, name, parent_id, intro, blurb, image, sort_order, seo_title, seo_description, faqs) values ('cleaning', 'Cleaning', null, 'Cleaning essentials at City Seller include spin mops, brooms, microfibre cloths and scrubbers that make daily jhadu-pocha faster. They are built for Indian floors, tiles and kitchens.', 'Spin mops, soft brooms and microfibre cloths for faster daily cleaning.', '/placeholders/categories/cleaning.svg', 2, null, null, '[{"q":"Are spin mop refills available separately?","a":"Yes. Search for mop refills or contact customer care with your order number."},{"q":"Can microfibre cloths be machine washed?","a":"Yes, wash them warm without fabric softener so they keep absorbing well."},{"q":"Which mop is best for marble floors?","a":"A microfibre spin mop with a well-wrung head is gentle on marble and leaves less water behind."}]'::jsonb) on conflict (slug) do nothing;
insert into public.categories (slug, name, parent_id, intro, blurb, image, sort_order, seo_title, seo_description, faqs) values ('bathroom', 'Bathroom', null, 'Bathroom products at City Seller include rust-proof shelves, soap dispensers and anti-slip mats for safer, tidier bathrooms. Most install without drilling.', 'No-drill shelves, dispensers and anti-slip mats for safer bathrooms.', '/placeholders/categories/bathroom.svg', 3, null, null, '[{"q":"Will adhesive shelves hold on bathroom tiles?","a":"Yes, on smooth, dry, clean tiles. Leave the adhesive to set for 24 hours before loading the shelf."},{"q":"Are the shelves rust-proof?","a":"Our bathroom shelves are aluminium or stainless steel, which resist rust in humid bathrooms."},{"q":"Can bath mats be machine washed?","a":"Most can on a gentle cycle. Check the care row in each product''s specifications."}]'::jsonb) on conflict (slug) do nothing;
insert into public.categories (slug, name, parent_id, intro, blurb, image, sort_order, seo_title, seo_description, faqs) values ('home-decor', 'Home Décor', null, 'Home Décor at City Seller brings handmade wall hangings, ceramic vases and warm lighting that make a room feel finished without a big budget.', 'Macramé, ceramic vases and fairy lights for a warm, lived-in look.', '/placeholders/categories/home-decor.svg', 4, null, null, '[{"q":"Are the décor items handmade?","a":"Items marked handmade are crafted by small workshops, so small variations in knots, glaze or shade are normal."},{"q":"Are LED string lights safe for indoor use?","a":"Yes. They run on low voltage and stay cool to the touch."},{"q":"Do vases hold water?","a":"Glazed ceramic vases hold water. Unglazed or decorative ones say \"dry flowers only\" in their specs."}]'::jsonb) on conflict (slug) do nothing;
insert into public.categories (slug, name, parent_id, intro, blurb, image, sort_order, seo_title, seo_description, faqs) values ('home-improvement', 'Home Improvement', null, 'Home Improvement covers small fixes like adhesive hooks and door draft stoppers that you can install yourself in minutes, with no tools or drilling.', 'No-drill hooks and quick fixes you can install in minutes.', '/placeholders/categories/home-improvement.svg', 5, null, null, '[{"q":"How much weight can adhesive hooks hold?","a":"Each product lists its tested load in the specs. Stay below it and wait 24 hours before hanging anything."},{"q":"Do these work on painted walls?","a":"They work best on smooth tiles, glass, metal and gloss paint. Textured or matte walls reduce grip."},{"q":"Can I remove hooks without damaging the wall?","a":"Warm the adhesive with a hair dryer for a minute and peel slowly."}]'::jsonb) on conflict (slug) do nothing;
