insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_008', 'under-sink-organiser-2tier', (select id from public.categories where slug = 'storage'), (select id from public.categories where slug = 'shelves-racks'), 'Under-Sink Organiser, 2 Tier with Sliding Basket', 'A two-tier sliding organiser that fits around sink pipes and turns the cabinet under your sink into usable storage.', 'The lower basket slides out on rails so cleaning supplies at the back are easy to reach. The narrow frame fits beside drain pipes, and the open design lets moisture dry quickly.', array['Assemble the frame and click the baskets onto the rails.', 'Place it beside the pipes and load bottles upright.', 'Wipe spills promptly.']::text[], '[{"label":"Material","value":"PP plastic with steel rails"},{"label":"Tiers","value":"2"},{"label":"Dimensions","value":"38 x 22 x 36 cm"},{"label":"Colour","value":"White"}]'::jsonb, 'Plastic', 'White', 699, 1299, 'https://www.meesho.com/search?q=Under-Sink%20Organiser%2C%202%20Tier%20with%20Sliding%20Basket', 420, '2026-10-28T15:44:09.841Z', 4, 64, 0, false, false, '[{"q":"Will it fit my cabinet?","a":"It needs a cabinet at least 40 cm wide, 24 cm deep and 38 cm high."},{"q":"Can it be used in the bathroom?","a":"Yes, it suits bathroom vanities too."},{"q":"When will it be back in stock?","a":"Contact customer care and we will tell you the expected restock date."}]'::jsonb, '2026-09-11T15:44:09.841Z') on conflict (slug) do nothing;
