insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_010', 'microfibre-cloth-pack-10', (select id from public.categories where slug = 'cleaning'), (select id from public.categories where slug = 'cleaning-tools'), 'Microfibre Cleaning Cloths, Pack of 10', 'Ten 40 x 40 cm, 340 GSM microfibre cloths that wipe kitchens, glass and cars streak-free with just water.', 'Dense 340 GSM microfibre picks up dust and grease without chemicals and holds several times its weight in water. Four colours help keep kitchen, bathroom, glass and car cloths separate.', array['Use dry for dust, damp for grease.', 'Machine wash warm with no fabric softener.', 'Air dry; do not iron.']::text[], '[{"label":"Material","value":"80% polyester, 20% polyamide"},{"label":"Size","value":"40 x 40 cm"},{"label":"Thickness","value":"340 GSM"},{"label":"Pack contains","value":"10 cloths in 4 colours"}]'::jsonb, 'Microfibre', 'Multicolour', 249, 499, 'https://www.meesho.com/search?q=Microfibre%20Cleaning%20Cloths%2C%20Pack%20of%2010', 120, '2026-11-11T15:44:09.841Z', 4.6, 892, 50, true, false, '[{"q":"Do they leave lint on glass?","a":"No, microfibre is lint-free and gives streak-free glass."},{"q":"How many washes do they last?","a":"Hundreds, if washed without fabric softener."},{"q":"Are they safe for car paint?","a":"Yes, they are soft enough for car paint and dashboards."}]'::jsonb, '2026-09-19T15:44:09.841Z') on conflict (slug) do nothing;
