insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_011', 'kitchen-sink-scrubber-set', (select id from public.categories where slug = 'cleaning'), (select id from public.categories where slug = 'cleaning-tools'), 'Kitchen Sink Scrubber Set with Holder', 'A sink-side set with a soap-dispensing brush, two sponges and a drain-hole holder that keeps your sink counter dry.', 'Fill the brush handle with dishwash liquid and press the button to release a little as you scrub. The holder drains water back into the sink so sponges dry faster and smell less.', array['Fill the handle with liquid dishwash.', 'Press the button to release soap while scrubbing.', 'Rinse sponges and place them in the holder to dry.']::text[], '[{"label":"Material","value":"PP plastic, nylon bristles, polyurethane sponge"},{"label":"Pack contains","value":"1 brush, 2 sponges, 1 holder"},{"label":"Colour","value":"Grey"}]'::jsonb, 'Plastic', 'Grey', 199, 399, 'https://www.meesho.com/search?q=Kitchen%20Sink%20Scrubber%20Set%20with%20Holder', 95, '2026-10-23T15:44:09.841Z', 4, 120, 50, false, false, '[{"q":"Will the brush scratch non-stick pans?","a":"Use the soft sponge side for non-stick; the brush suits steel vessels."},{"q":"Does the holder stick to the sink?","a":"It hangs over the sink edge, so no adhesive is needed."},{"q":"How often should I replace sponges?","a":"Every 3 to 4 weeks for hygiene."}]'::jsonb, '2026-09-23T15:44:09.841Z') on conflict (slug) do nothing;
