insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_012', 'soft-grass-broom', (select id from public.categories where slug = 'cleaning'), (select id from public.categories where slug = 'mops-brooms'), 'Soft Grass Broom (Phool Jhadu), Long Handle', 'A traditional soft grass phool jhadu with a long handle, for sweeping fine dust off tiles and marble without bending.', 'Tightly bound natural grass catches fine dust and hair. The 100 cm handle means less bending, and the stitched band keeps the bristles from shedding.', array['Sweep in short strokes towards you.', 'Tap the broom outdoors to shake out dust.', 'Hang it bristles-down to keep its shape.']::text[], '[{"label":"Material","value":"Natural grass, plastic grip"},{"label":"Length","value":"100 cm"},{"label":"Colour","value":"Natural"}]'::jsonb, 'Natural fibre', 'Natural', 279, 449, 'https://www.meesho.com/search?q=Soft%20Grass%20Broom%20(Phool%20Jhadu)%2C%20Long%20Handle', 150, '2026-11-06T15:44:09.841Z', 4.2, 233, 50, false, false, '[{"q":"Does it shed?","a":"Some loose strands come out in the first few uses; this stops quickly."},{"q":"Is it good for outdoor use?","a":"It is best indoors. Use a hard broom for rough outdoor surfaces."},{"q":"Can I wash it?","a":"Rinse only the tips if needed and dry it in the sun."}]'::jsonb, '2026-09-27T15:44:09.841Z') on conflict (slug) do nothing;
