insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_013', 'bathroom-corner-shelf-2pc', (select id from public.categories where slug = 'bathroom'), (select id from public.categories where slug = 'bath-storage'), 'No-Drill Bathroom Corner Shelf, Set of 2', 'Two rust-proof aluminium corner shelves that stick to tiles without drilling, for shampoo, soap and toiletries.', 'A strong waterproof adhesive pad holds each shelf firmly on smooth tiles, and the open base drains water so nothing stays soggy. Each shelf carries up to 5 kg.', array['Clean and dry the tile and mark the position.', 'Peel the backing and press the pad firmly for 30 seconds.', 'Wait 24 hours, then hang the shelf on the pad hooks.']::text[], '[{"label":"Material","value":"Space aluminium"},{"label":"Pack contains","value":"2 shelves, 2 adhesive pads"},{"label":"Dimensions (each)","value":"28 x 20 x 4 cm"},{"label":"Load capacity","value":"5 kg per shelf"},{"label":"Colour","value":"Silver"}]'::jsonb, 'Aluminium', 'Silver', 599, 1199, 'https://www.meesho.com/search?q=No-Drill%20Bathroom%20Corner%20Shelf%2C%20Set%20of%202', 340, '2026-11-10T15:44:09.841Z', 4.3, 276, 50, true, false, '[{"q":"Will it hold on textured tiles?","a":"It needs smooth tiles. Textured or rough tiles reduce grip."},{"q":"Can I reuse the adhesive?","a":"Each pad is single-use. Spare pads are available on request."},{"q":"Is it rust-proof?","a":"Yes, aluminium does not rust."}]'::jsonb, '2026-10-01T15:44:09.841Z') on conflict (slug) do nothing;
