insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_014', 'ceramic-soap-dispenser-set', (select id from public.categories where slug = 'bathroom'), (select id from public.categories where slug = 'bath-accessories'), 'Ceramic Soap Dispenser and Tray Set, 3 pc', 'A matte ceramic set with a soap dispenser, toothbrush tumbler and tray that gives your washbasin a calm, matched look.', 'Each piece is glazed inside to resist water stains and finished matte outside. The dispenser has a rust-free pump and holds 350 ml of liquid soap or hand wash.', array['Unscrew the pump to fill.', 'Wipe pieces weekly with a damp cloth.', 'Do not drop on hard floors.']::text[], '[{"label":"Material","value":"Ceramic with ABS pump"},{"label":"Pack contains","value":"Dispenser, tumbler, tray"},{"label":"Dispenser capacity","value":"350 ml"},{"label":"Colour","value":"Matte white"}]'::jsonb, 'Ceramic', 'White', 699, 1399, 'https://www.meesho.com/search?q=Ceramic%20Soap%20Dispenser%20and%20Tray%20Set%2C%203%20pc', 410, '2026-11-09T15:44:09.841Z', 4.4, 88, 50, false, false, '[{"q":"Does the pump rust?","a":"No, the pump is ABS plastic with a stainless spring."},{"q":"Can I use it for sanitiser?","a":"Yes, any liquid soap, hand wash or gel sanitiser works."},{"q":"Is it fragile?","a":"It is ceramic, so handle with care. Breakage in transit is covered by our return policy."}]'::jsonb, '2026-10-05T15:44:09.841Z') on conflict (slug) do nothing;
