insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_015', 'anti-slip-bath-mat', (select id from public.categories where slug = 'bathroom'), (select id from public.categories where slug = 'bath-accessories'), 'Anti-Slip Microfibre Bath Mat (40 x 60 cm)', 'A 40 x 60 cm quick-dry microfibre bath mat with a rubber backing that grips wet floors to prevent slips.', 'Soft chenille microfibre absorbs water from your feet quickly, and the rubber dot backing stops the mat sliding on wet tiles.', array['Place on a dry floor outside the shower.', 'Shake out daily.', 'Machine wash gentle and line dry.']::text[], '[{"label":"Material","value":"Chenille microfibre, TPR rubber backing"},{"label":"Size","value":"40 x 60 cm"},{"label":"Care","value":"Machine wash gentle, line dry"},{"label":"Colour","value":"Grey"}]'::jsonb, 'Microfibre', 'Grey', 349, 699, 'https://www.meesho.com/search?q=Anti-Slip%20Microfibre%20Bath%20Mat%20(40%20x%2060%20cm)', 185, '2026-11-05T15:44:09.841Z', 4.2, 190, 50, false, true, '[{"q":"Can it be used inside the shower?","a":"It is meant for outside the shower. Inside, use a perforated rubber shower mat."},{"q":"Will the backing damage tiles?","a":"No, the TPR backing is safe on tiles and stone."},{"q":"Does colour bleed in the wash?","a":"Wash separately the first time."}]'::jsonb, '2026-10-09T15:44:09.841Z') on conflict (slug) do nothing;
