insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_016', 'macrame-wall-hanging', (select id from public.categories where slug = 'home-decor'), (select id from public.categories where slug = 'wall-decor'), 'Handmade Macramé Wall Hanging, Boho Style', 'A handmade cotton macramé hanging on a wooden dowel that adds soft texture to a bare wall above a bed or sofa.', 'Knotted by hand from soft cotton cord, each piece varies slightly, which is part of its charm. It hangs from a sanded wooden dowel and needs just one nail or adhesive hook.', array['Hang from a single nail or adhesive hook.', 'Comb the fringe gently with your fingers to straighten it.', 'Dust with a hair dryer on the cool setting.']::text[], '[{"label":"Material","value":"Cotton cord, wooden dowel"},{"label":"Size","value":"45 cm wide x 80 cm long"},{"label":"Craft","value":"Handmade"},{"label":"Colour","value":"Off-white"}]'::jsonb, 'Cotton', 'Off-white', 499, 999, 'https://www.meesho.com/search?q=Handmade%20Macram%C3%A9%20Wall%20Hanging%2C%20Boho%20Style', 280, '2026-11-02T15:44:09.841Z', 4.6, 74, 50, false, false, '[{"q":"Is a nail included?","a":"No. One small nail or adhesive hook is enough."},{"q":"Is it exactly like the photo?","a":"It is handmade, so knots and length may vary slightly."},{"q":"Can I wash it?","a":"Hand wash cold in mild detergent and dry flat."}]'::jsonb, '2026-10-13T15:44:09.841Z') on conflict (slug) do nothing;
