insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_018', 'led-string-lights-10m', (select id from public.categories where slug = 'home-decor'), (select id from public.categories where slug = 'lighting'), 'Warm White LED String Lights, 10 m (USB)', 'A 10 m, 100-LED warm white fairy light string powered by USB, for festive décor, balconies and bedroom walls.', 'Thin copper wire bends around frames, plants and mirrors. Eight lighting modes are set by a small controller, and the lights run from any USB adapter or power bank.', array['Plug into a USB adapter or power bank.', 'Press the controller button to change modes.', 'For outdoor use, keep the controller dry.']::text[], '[{"label":"Length","value":"10 m"},{"label":"LEDs","value":"100"},{"label":"Power","value":"USB 5 V"},{"label":"Modes","value":"8"},{"label":"Colour","value":"Warm white"}]'::jsonb, 'Copper wire', 'Warm white', 299, 599, 'https://www.meesho.com/search?q=Warm%20White%20LED%20String%20Lights%2C%2010%20m%20(USB)', 140, '2026-11-10T15:44:09.842Z', 4.3, 455, 50, false, false, '[{"q":"Is a USB adapter included?","a":"No. Any phone charger or power bank works."},{"q":"Can they be used outdoors?","a":"The string is splash-resistant; keep the controller and plug dry."},{"q":"Do they get hot?","a":"No, LEDs stay cool to the touch."}]'::jsonb, '2026-10-21T15:44:09.842Z') on conflict (slug) do nothing;
