insert into public.products (legacy_id, slug, category_id, subcategory_id, title, summary, description, how_to_use, specs, material, colour, price, mrp, meesho_url, meesho_price, price_checked_at, rating, review_count, stock, is_bestseller, is_flash_sale, faqs, created_at) values ('prd_019', 'adhesive-wall-hooks-12pc', (select id from public.categories where slug = 'home-improvement'), (select id from public.categories where slug = 'hooks-hardware'), 'Heavy-Duty Adhesive Wall Hooks, Pack of 12', 'Twelve no-drill stainless steel hooks that hold up to 5 kg each on tiles, glass and smooth walls, for towels, bags and keys.', 'A clear waterproof adhesive pad grips smooth surfaces in kitchens and bathrooms, and the steel hook does not rust. They suit rented homes where drilling is not allowed.', array['Clean the surface with spirit and let it dry.', 'Press the hook firmly for 30 seconds.', 'Wait 24 hours before hanging anything.']::text[], '[{"label":"Material","value":"Stainless steel hook, acrylic adhesive pad"},{"label":"Pack contains","value":"12 hooks"},{"label":"Load capacity","value":"Up to 5 kg each (tested on tiles)"},{"label":"Colour","value":"Silver"}]'::jsonb, 'Steel', 'Silver', 199, 399, 'https://www.meesho.com/search?q=Heavy-Duty%20Adhesive%20Wall%20Hooks%2C%20Pack%20of%2012', 85, '2026-11-11T15:44:09.842Z', 4.2, 701, 50, true, false, '[{"q":"Do they work on painted walls?","a":"Only on smooth gloss paint. Matte or textured paint reduces grip."},{"q":"Can I remove them?","a":"Warm the pad with a hair dryer for a minute and peel slowly."},{"q":"Are they waterproof?","a":"Yes, they are fine in bathrooms once the adhesive has set."}]'::jsonb, '2026-10-25T15:44:09.842Z') on conflict (slug) do nothing;
